   226  void SubMac::StartCsmaBackoff(void)
   227  {
   228      uint32_t backoff;
   229      uint32_t backoffExponent = kMinBE + mTransmitRetries + mCsmaBackoffs;
   230
   231      SetState(kStateCsmaBackoff);
   232
   233      VerifyOrExit(ShouldHandleCsmaBackOff(), BeginTransmit());
   234
   235  #if OPENTHREAD_CONFIG_DISABLE_CSMA_CA_ON_LAST_ATTEMPT
